sys_script_include.script:
var needit_ex_GetEmailAddress = Class.create();
needit_ex_GetEmailAddress.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    needit_ex_getMail: function() {
			var userRecord = new GlideRecord("sys_user");
			gs.info("data fetch to the sys_user tabele");
			// userRecord.get(this.getParameter('sysparm_userID'));
			var userID=this.getParameter('sysparm_userID')

			if (userID && userRecord.get(userID)) {
				// getValue is safer in Scoped Apps
				return userRecord.getValue('email'); 
		}
		return '';
	},

    type: 'needit_ex_GetEmailAddress'
});
